/**
 * @description : Bottom Navigation Bar – role-based tabs for Student & Staff.
 *                Student:  Home | Classes | Homework | Attendance | Profile
 *                Staff:    Home | Classes | Students | Attendance | Profile
 * @author : Institute User Portal
 * @date   : Aug-2026
 */

import React, { useContext } from 'react';
import {
  FaHome,
  FaCalendarAlt,
  FaBookOpen,
  FaClipboardList,
  FaUserCircle,
  FaUsers,
  FaChalkboardTeacher,
} from 'react-icons/fa';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../App';

const NavBar = () => {
  const location = useLocation();
  const navigate  = useNavigate();
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const typ  = String(user.typ || '').toUpperCase();

  const isActive = (path) => location.pathname === path;

  /* ─── Student tabs ─── */
  const studentTabs = [
    { label: 'Home',       icon: <FaHome />,           path: '/dashboard' },
    { label: 'Classes',    icon: <FaCalendarAlt />,    path: '/timetable' },
    { label: 'Homework',   icon: <FaBookOpen />,       path: '/homework' },
    { label: 'Attendance', icon: <FaClipboardList />,  path: '/attendance' },
    { label: 'Profile',    icon: <FaUserCircle />,     path: '/profile' },
  ];

  /* ─── Staff tabs ─── */
  const staffTabs = [
    { label: 'Home',       icon: <FaHome />,                path: '/dashboard' },
    { label: 'Classes',    icon: <FaChalkboardTeacher />,   path: '/timetable' },
    { label: 'Students',   icon: <FaUsers />,               path: '/students' },
    { label: 'Attendance', icon: <FaClipboardList />,       path: '/attendance' },
    { label: 'Profile',    icon: <FaUserCircle />,          path: '/staff-profile' },
  ];

  const tabs = typ === 'STAFF' ? staffTabs : studentTabs;

  return (
    <nav className="user-bottom-nav">
      {tabs.map((tab) => (
        <Link
          key={tab.path}
          to={tab.path}
          className={`user-bottom-nav-item${isActive(tab.path) ? ' active' : ''}`}
        >
          <span className="user-bottom-nav-icon">{tab.icon}</span>
          <span>{tab.label}</span>
        </Link>
      ))}
    </nav>
  );
};

export default NavBar;
